package ccxt

type Massive struct {
   *MassiveCore
   Core *MassiveCore
   exchangeTyped *ExchangeTyped
}

func NewMassive(userConfig map[string]any) *Massive {
   p := NewMassiveCore()
   p.Init(userConfig)
   return &Massive{
       MassiveCore: p,
       Core:  p,
       exchangeTyped: NewExchangeTyped(&p.Exchange),
   }
}
func NewMassiveFromCore(core *MassiveCore) *Massive {
   return &Massive{
       MassiveCore: core,
       Core:  core,
       exchangeTyped: NewExchangeTyped(&core.Exchange),
   }
}

